export const NPC_EVENT_BACKGROUNDS = Array.from(
  { length: 6 },
  (_, i) => `sprites/rpg/events/background-${i}.webp`,
);
export function storyEventArt(index: number, variant: number) {
  return `sprites/rpg/events/story-${variant * 6 + index}.webp`;
}
export const STORY_VARIANT_ENGLISH: Record<string, string> = {},
  STORY_VARIANT_HIRAGANA: Record<string, string> = {};
for (const variants of STORY_VARIANTS)
  for (const v of variants)
    if (v) {
      for (const item of [
        v.title,
        v.goal,
        v.intro,
        v.discovery,
        v.returning,
        ...v.endings,
      ]) {
        STORY_VARIANT_ENGLISH[item.ja] = item.en;
        STORY_VARIANT_HIRAGANA[item.ja] = item.hira;
      }
    }

for(const variants of STORY_VARIANTS)for(const v of variants)if(v){const ja=`${v.goal.ja}を調べてきて。道は地図で確認できるよ。`;STORY_VARIANT_ENGLISH[ja]=`Investigate ${v.goal.en}. Check your journal for the route.`;STORY_VARIANT_HIRAGANA[ja]=`${v.goal.hira}をしらべてきて。みちはちずでかくにんできるよ。`;}

const CONTEXT_ENDINGS=[[{"ja": "灯りを船の道しるべにするか、願いを込めて川へ返すか。", "en": "Use the lights as navigation beacons, or return them to the river with wishes?", "hira": "あかりをふねのみちしるべにするか、ねがいをこめてかわへかえすか。"}, {"ja": "港の標識が夜の船を導き、帰りを待つ家々に安心が戻った。", "en": "Harbor beacons guide boats home and comfort the waiting families.", "hira": "みなとのひょうしきがよるのふねをみちびき、かえりをまついえいえにあんしんがもどった。"}, {"ja": "ミオと灯りを川へ返した。ゆっくり流れる光を、岸辺の人々が見送った。", "en": "You and Mio release the lanterns, watched quietly by people on the shore.", "hira": "みおとあかりをかわへかえした。ゆっくりながれるひかりを、きしべのひとびとがみおくった。"}], [{"ja": "薬を運ぶ便を作るか、困った旅人が使える渡し札を残すか。", "en": "Start a medicine ferry, or keep tokens available for travelers in need?", "hira": "くすりをはこぶびんをつくるか、こまったたびびとがつかえるわたしふだをのこすか。"}, {"ja": "渡し船に薬の定期便が生まれ、川向こうの診療所へ荷物が届いた。", "en": "A regular medicine ferry brings supplies to the clinic across the river.", "hira": "わたしぶねにくすりのていきびんがうまれ、かわむこうのしんりょうじょへにもつがとどいた。"}, {"ja": "ミオは渡し札を入口に置いた。財布をなくした旅人も川を渡れるようになった。", "en": "Mio leaves ferry tokens at the landing so travelers who lose their purses can cross.", "hira": "みおはわたしふだをいりぐちにおいた。さいふをなくしたたびびともかわをわたれるようになった。"}], [{"ja": "町に水位の掲示板を作るか、船乗りの手帳に写して渡すか。", "en": "Build a town water-level noticeboard, or copy the notes into sailors’ journals?", "hira": "まちにすいいのけいじばんをつくるか、ふなのりのてちょうにうつしてわたすか。"}, {"ja": "市場の掲示板が水位を知らせ、増水前に荷物を避難できるようになった。", "en": "The market noticeboard gives flood warnings in time to protect goods.", "hira": "いちばのけいじばんがすいいをしらせ、ぞうすいまえににもつをひなんできるようになった。"}, {"ja": "水位を読む手帳が船乗りたちに渡り、旅先でも安全な岸を選べるようになった。", "en": "Sailors receive water-level journals and choose safer banks on their journeys.", "hira": "すいいをよむてちょうがふなのりたちにわたり、たびさきでもあんぜんなきしをえらべるようになった。"}], [{"ja": "商隊の季節表を作るか、道標に星図を残すか。", "en": "Make a seasonal caravan schedule, or leave the star chart on the waystone?", "hira": "しょうたいのきせつひょうをつくるか、みちしるべにせいずをのこすか。"}, {"ja": "季節に合う商路が選ばれ、町の市場に新しい品物が届いた。", "en": "Seasonal routes bring new goods safely to the town market.", "hira": "きせつにあうしょうろがえらばれ、まちのいちばにあたらしいしなものがとどいた。"}, {"ja": "道標の星図を見上げながら、見知らぬ旅人同士が道を教え合った。", "en": "Strangers gather at the waystone’s chart and share directions beneath the stars.", "hira": "みちしるべのせいずをみあげながら、みしらぬたびびとどうしがみちをおしえあった。"}], [{"ja": "水場を町の井戸へつなぐか、砂丘の休憩所として残すか。", "en": "Connect the water source to town wells, or keep it as a dune rest stop?", "hira": "みずばをまちのいどへつなぐか、さきゅうのきゅうけいじょとしてのこすか。"}, {"ja": "古い水場から井戸へ水が戻り、町の花壇がまた色づいた。", "en": "Water returns to the town wells and brings color back to the flowerbeds.", "hira": "ふるいみずばからいどへみずがもどり、まちのかだんがまたいろづいた。"}, {"ja": "砂丘に小さな水場の目印が立った。サハは訪れる旅人へ水を分けた。", "en": "A marker identifies the dune watering place, where Saha shares water with travelers.", "hira": "さきゅうにちいさなみずばのめじるしがたった。さははおとずれるたびびとへみずをわけた。"}], [{"ja": "町に修理所を作るか、道沿いの貸し道具箱にするか。", "en": "Start a town repair shop, or make a roadside tool-lending box?", "hira": "まちにしゅうりじょをつくるか、みちぞいのかしどうぐばこにするか。"}, {"ja": "町の修理所に商隊が立ち寄り、職人たちの仕事が増えた。", "en": "Caravans stop at the new repair shop, bringing work to local craftspeople.", "hira": "まちのしゅうりじょにしょうたいがたちより、しょくにんたちのしごとがふえた。"}, {"ja": "貸し道具箱には、使った旅人がお礼の部品を残すようになった。", "en": "Travelers leave spare parts as thanks after borrowing tools from the roadside box.", "hira": "かしどうぐばこには、つかったたびびとがおれいのぶひんをのこすようになった。"}], [{"ja": "救助所の合図にするか、旅人ひとりひとりに笛を渡すか。", "en": "Use whistles at rescue stations, or give one to every traveler?", "hira": "きゅうじょじょのあいずにするか、たびびとひとりひとりにふえをわたすか。"}, {"ja": "雪道の救助所に合図が決まり、吹雪の日にも連絡が取れるようになった。", "en": "Rescue stations establish whistle signals that work even in blizzards.", "hira": "ゆきみちのきゅうじょじょにあいずがきまり、ふぶきのひにもれんらくがとれるようになった。"}, {"ja": "ユキは小さな笛を旅人へ配った。別れても、互いを呼べる音が残った。", "en": "Yuki gives travelers small whistles, leaving a way to call one another after parting.", "hira": "ゆきはちいさなふえをたびびとへくばった。わかれても、たがいをよべるおとがのこった。"}], [{"ja": "灯台の観測に使うか、みんなで星を見る会を開くか。", "en": "Use it at the lighthouse, or host a public stargazing evening?", "hira": "とうだいのかんそくにつかうか、みんなでほしをみるかいをひらくか。"}, {"ja": "望遠鏡で星の位置を測り、灯台の光が正しい航路を照らした。", "en": "Star measurements help the lighthouse illuminate the right route.", "hira": "ぼうえんきょうでほしのいちをはかり、とうだいのひかりがただしいこうろをてらした。"}, {"ja": "星見会で子どもたちが初めて星の輪を見た。ユキも隣で笑っていた。", "en": "Children see a star’s halo for the first time, with Yuki smiling beside them.", "hira": "ほしみかいでこどもたちがはじめてほしのわをみた。ゆきもとなりでわらっていた。"}], [{"ja": "峠の食堂に備えるか、道を歩く人へお弁当を配るか。", "en": "Stock a pass shelter kitchen, or distribute lunches to people on the trail?", "hira": "とうげのしょくどうにそなえるか、みちをあるくひとへおべんとうをくばるか。"}, {"ja": "峠の食堂から湯気が上がり、寒い旅人が同じ食卓を囲んだ。", "en": "Steam rises from the pass kitchen as cold travelers gather around one table.", "hira": "とうげのしょくどうからゆげがあがり、さむいたびびとがおなじしょくたくをかこんだ。"}, {"ja": "手紙付きのお弁当が旅人へ渡った。食べ終えた人がお返しの便りを残した。", "en": "Travelers receive lunches with letters, then leave replies after their meals.", "hira": "てがみつきのおべんとうがたびびとへわたった。たべおえたひとがおかえしのたよりをのこした。"}], [{"ja": "町の時報にするか、やさしい朝の歌を残すか。", "en": "Make it the town time signal, or preserve its gentle morning song?", "hira": "まちのじほうにするか、やさしいあさのうたをのこすか。"}, {"ja": "機械鳥が広場で時を知らせ、人々は余裕を持って待ち合わせるようになった。", "en": "The bird announces time in the square, making meetings less rushed.", "hira": "きかいどりがひろばでときをしらせ、ひとびとはよゆうをもってまちあわせるようになった。"}, {"ja": "トワは音を小さく調整した。機械鳥の歌で、窓辺の朝が少し明るくなった。", "en": "Towa softens the song, and mornings by the window grow a little brighter.", "hira": "とわはおとをちいさくちょうせいした。きかいどりのうたで、まどべのあさがすこしあかるくなった。"}], [{"ja": "職人たちの記録に残すか、家族へ時計を返すか。", "en": "Keep it with the craftspeople’s records, or return it to their family?", "hira": "しょくにんたちのきろくにのこすか、かぞくへとけいをかえすか。"}, {"ja": "町の展示室に時計と職人の名前が並び、若い人たちが歴史を学んだ。", "en": "The watch and the makers’ names enter the town exhibit, teaching younger visitors its history.", "hira": "まちのてんじしつにとけいとしょくにんのなまえがならび、わかいひとたちがれきしをまなんだ。"}, {"ja": "時計は職人の家族へ戻った。古い針が、家族の新しい時間を刻み始めた。", "en": "The watch returns to the family, its old hands marking their new moments.", "hira": "とけいはしょくにんのかぞくへもどった。ふるいはりが、かぞくのあたらしいじかんをきざみはじめた。"}], [{"ja": "町の共通の休日にするか、それぞれの休み方を記すか。", "en": "Choose a shared town holiday, or record everyone’s own way to rest?", "hira": "まちのきょうつうのきゅうじつにするか、それぞれのやすみかたをしるすか。"}, {"ja": "新しい休日に市場で食事会が開かれ、普段会えない友達が集まった。", "en": "A holiday market dinner brings together friends who rarely meet.", "hira": "あたらしいきゅうじつにいちばでしょくじかいがひらかれ、ふだんあえないともだちがあつまった。"}, {"ja": "暦盤に人それぞれの休みの印が刻まれ、町は無理に同じ歩幅を求めなくなった。", "en": "Personal rest marks on the calendar let the town respect different paces of life.", "hira": "こよみばんにひとそれぞれのやすみのしるしがきざまれ、まちはむりにおなじほはばをもとめなくなった。"}]];
for(let i=0;i<CONTEXT_ENDINGS.length;i++){const v=STORY_VARIANTS[2+Math.floor(i/3)][1+i%3]!;v.returning=CONTEXT_ENDINGS[i][0];v.endings=CONTEXT_ENDINGS[i].slice(1);for(const item of [v.returning,...v.endings]){STORY_VARIANT_ENGLISH[item.ja]=item.en;STORY_VARIANT_HIRAGANA[item.ja]=item.hira;}}
